import * as T from 'three';
import{GLTFLoader}from'./vendor/GLTFLoader.js';
import{focus,cost,CHANNELS}from'./engine.js';
const colors=[0xb84b32,0xb89036,0x3b7195],hex=['#b84b32','#b89036','#3b7195'];
export async function board(el,onSelect){
 const scene=new T.Scene();scene.background=new T.Color('#d9d1bc');const camera=new T.OrthographicCamera(-10,10,7,-7,.1,150),renderer=new T.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.shadowMap.enabled=true;el.append(renderer.domElement);scene.add(new T.HemisphereLight(0xfff8df,0x536158,2.5));const sun=new T.DirectionalLight(0xffffff,3);sun.position.set(-8,14,8);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);scene.add(sun);const group=new T.Group(),dynamic=new T.Group();scene.add(group);group.add(dynamic);const meshes=[];
 function box(w,h,d,color,x,y,z,parent=group){const m=new T.Mesh(new T.BoxGeometry(w,h,d),new T.MeshStandardMaterial({color,roughness:.95}));m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
 box(19,.4,12,0x41584b,0,-.4,0);box(18.7,.08,11.7,0xd7c8a5,0,-.15,0);
 function plaque(lines,x,z,w,h,bg='#f4e9cd',accent='#163e39',id=null){let c=document.createElement('canvas');c.width=384;c.height=Math.round(384*h/w);let ctx=c.getContext('2d');ctx.fillStyle=bg;ctx.fillRect(0,0,c.width,c.height);ctx.fillStyle=accent;ctx.fillRect(0,0,14,c.height);ctx.textAlign='center';let y=0;for(const l of lines){y+=l.gap??46;ctx.fillStyle=l.color||'#173c35';ctx.font=(l.bold?'bold ':'')+(l.size||32)+'px '+(l.serif?'Georgia':'sans-serif');let words=l.text.split(' '),row='',yy=y;for(let word of words){let trial=row?row+' '+word:word;if(ctx.measureText(trial).width>c.width-60&&row){ctx.fillText(row,c.width/2,yy);yy+=(l.size||32)*1.15;row=word}else row=trial}ctx.fillText(row,c.width/2,yy);y=yy;}let tx=new T.CanvasTexture(c);tx.anisotropy=renderer.capabilities.getMaxAnisotropy();const p=new T.Mesh(new T.PlaneGeometry(w,h),new T.MeshBasicMaterial({map:tx,side:T.DoubleSide}));p.rotation.x=-Math.PI/2;p.position.set(x,.16,z);dynamic.add(p);if(id!==null){p.userData.slot=id;meshes.push(p)}return p}
 const faces=await(await fetch('./assets/dice-faces.json')).json(),g=await new GLTFLoader().loadAsync('./assets/dice.glb'),base=g.scene,bounds=new T.Box3().setFromObject(base),sz=bounds.getSize(new T.Vector3());base.position.sub(bounds.getCenter(new T.Vector3()));let dice=[];
 for(let i=0;i<3;i++){let root=new T.Group(),model=base.clone(true);model.traverse(m=>{if(m.isMesh){m.material=m.material.clone();if(m.material.name==='white')m.material.color.setHex(colors[i]);m.castShadow=true}});root.add(model);root.scale.setScalar(.9/Math.max(sz.x,sz.y,sz.z));group.add(root);dice.push(root)}
 let yaw=0,pitch=1.25,zoom=1,pan=new T.Vector3(),drag=null,lastState,lastSelection=-1;const ray=new T.Raycaster(),point=new T.Vector2();
 function render(){const w=el.clientWidth,h=el.clientHeight,aspect=w/h,half=Math.max(6.6,10/aspect);renderer.setSize(w,h,false);camera.left=-half*aspect;camera.right=half*aspect;camera.top=half;camera.bottom=-half;camera.zoom=zoom;camera.position.set(Math.sin(yaw)*25*Math.cos(pitch),25*Math.sin(pitch),Math.cos(yaw)*25*Math.cos(pitch)).add(pan);camera.lookAt(pan);camera.updateProjectionMatrix();renderer.render(scene,camera)}
 function pick(e){const r=renderer.domElement.getBoundingClientRect();point.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);ray.setFromCamera(point,camera);const hit=ray.intersectObjects(meshes)[0];if(hit)onSelect(hit.object.userData.slot)}
 el.addEventListener('contextmenu',e=>e.preventDefault());el.addEventListener('pointerdown',e=>{drag={x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY,pan:e.shiftKey||e.button===2};el.setPointerCapture(e.pointerId)});el.addEventListener('pointermove',e=>{if(!drag)return;let dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(drag.pan){pan.x-=dx*.02/zoom;pan.z-=dy*.02/zoom}else{yaw-=dx*.008;pitch=Math.max(.2,Math.min(1.56,pitch+dy*.006))}drag.x=e.clientX;drag.y=e.clientY;render()});el.addEventListener('pointerup',e=>{if(drag&&Math.hypot(e.clientX-drag.startX,e.clientY-drag.startY)<6)pick(e);drag=null});el.addEventListener('pointercancel',()=>drag=null);el.addEventListener('wheel',e=>{e.preventDefault();zoom=Math.max(.55,Math.min(3,zoom*Math.exp(-e.deltaY*.001)));render()},{passive:false});new ResizeObserver(render).observe(el);
 const api={zoom(d){zoom=Math.max(.55,Math.min(3,zoom*d));render()},reset(){yaw=0;pitch=1.25;zoom=1;pan.set(0,0,0);render()},toggle(){pitch=pitch>1.4?1.0:1.56;yaw=0;render()},update(s,selected=-1){lastState=s;lastSelection=selected;while(dynamic.children.length){let c=dynamic.children[0];dynamic.remove(c);c.geometry?.dispose();c.material?.map?.dispose();c.material?.dispose()}meshes.length=0;const f=focus(s);plaque([{text:'DISCOURSE → ACCESS → CONTROL',size:14,bold:true,gap:17}],0,-5.3,15,.8);for(let row=0;row<3;row++){const z=-3.3+row*3.3;box(13.4,.04,3.05,s.mode==='pyramid'&&f===row?0xe3c773:0xbfbca2,2,.01,z,dynamic);plaque([{text:CHANNELS[row],size:38,bold:true,gap:46},{text:s.mode==='pyramid'?(f===row?'IN FOCUS · FREE':'OUTSIDE · 1 FAVOR'):'SUPPLY CHANNEL',size:25,gap:48}],-6.2,z+.7,4,1.1,'#eee3c7',hex[row]);let die=s.dice.find(d=>d.channel===row),di=s.dice.indexOf(die);dice[di].position.set(-6.2,.7,z-.55);dice[di].quaternion.setFromUnitVectors(new T.Vector3(...faces.find(f=>f.value===die.value).normal),new T.Vector3(0,1,0));plaque([{text:die.id+' = '+die.value,size:85,bold:true,gap:125}],-4.9,z-.65,1.2,.7,'#eee3c7',hex[di]);for(let col=0;col<4;col++){let x=-2.7+col*3.15,c=s.cards[s.market[col]];if(c.supply===row){let free=cost(s,col)===0;box(2.95,.12,2.75,selected===col?0x183e36:colors[row],x,.04,z,dynamic);plaque([{text:'MARKET '+(col+1)+' · '+(free?'FREE':'1 FAVOR'),size:31,bold:true,gap:47,color:free?'#30624d':'#91412b'},{text:c.title,size:36,serif:true,bold:true,gap:60},{text:'NEEDS '+CHANNELS[c.need],size:28,gap:52},{text:selected===col?'SELECTED · CONFIRM AT RIGHT':'CLICK TO INSPECT',size:22,gap:49}],x,z,2.8,2.55,selected===col?'#f6d47e':'#fcf2d9',hex[row],col)}else plaque([{text:'SLOT '+(col+1),size:23,gap:70,color:'#778175'},{text:'no '+CHANNELS[row].toLowerCase()+' supplier',size:23,gap:60,color:'#778175'}],x,z,2.8,2.55,'#ccd0b9','#a8af9d')}}plaque([{text:s.mode==='pyramid'?'Highest die opens its channel. A tie opens none.':'WINDOW: columns '+(s.window+1)+' & '+(s.window+2)+' are free.',size:13,gap:17}],1,5.3,15,.8);render()}};return api;
}
